package br.com.admeclesial.domain.financeiro;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="pagamento",schema="adm_eclesial") public class Pagamento { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Column(nullable=false,precision=15,scale=2) BigDecimal valor; @Column(name="data_pagamento",nullable=false) LocalDate dataPagamento; @Enumerated(EnumType.STRING) @Column(name="meio_pagamento",nullable=false,length=20) MeioPagamento meioPagamento; @Column(columnDefinition="text") String observacao; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public BigDecimal getValor(){return valor;} public LocalDate getDataPagamento(){return dataPagamento;} public MeioPagamento getMeioPagamento(){return meioPagamento;} public String getObservacao(){return observacao;} public void setValor(BigDecimal v){valor=v;} public void setDataPagamento(LocalDate v){dataPagamento=v;} public void setMeioPagamento(MeioPagamento v){meioPagamento=v;} public void setObservacao(String v){observacao=v;} }